// The two things the caller needs out of the session's answer: the H1, which the row
// stores as ARTICLE_TITLE and the entry point turns into the frozen slug, and the body,
// which carries one `<!-- asset:<type> -->` marker per requested asset. The word budget is
// checked here rather than trusted to the model: a mandatory count in a format is a count
// that gets invented when the real one is missing.
//
// A problem is reported as data (`PROBLEM`), never thrown: a draft that ran long or came
// back without a title is retried by the review loop below, and only a run that exhausts
// its attempts reports the reason to the caller.
//
// MAX_WORDS is required. The entry point resolves the row's budget and the 1200 default,
// so a value missing here is a caller bug: fail loudly rather than guess a bound.
const req = $('set_workflow_vars').first().json;
const max = Number(req.MAX_WORDS);
if (!isFinite(max) || max <= 0) throw new Error('MAX_WORDS is required and must be a positive number');
const read = (name) => {
  try {
    return $(name).first().json;
  } catch (e) {
    return null;
  }
};
// An HTTP Request node answers {data, headers, statusCode, statusMessage}; the payload is
// `data`. Read that first and keep the older `body` key, because the shape of the answer
// is the node's configuration and a silent fall-through here is an empty draft.
const answer = (res) => {
  if (!res) return '';
  if (typeof res.data === 'string') return res.data;
  return typeof res.body === 'string' ? res.body : '';
};
// The adapter serves article.md; a turn that answered 4xx or wrote nothing has no draft.
const fetched = read('fetch_article');
const fetchedText = answer(fetched);
let raw = '';
if (fetchedText) raw = fetchedText;
else raw = String($json.output || $json.text || '');
const posted = read('request_article');
let sessionProblem = '';
if (posted && Number(posted.statusCode || posted.status || 0) >= 400) {
  const status = Number(posted.statusCode || posted.status || 0);
  let reason = '';
  try {
    const body = JSON.parse(answer(posted) || '{}');
    reason = String((body.error && body.error.message) || body.message || '').trim();
  } catch (e) {
    reason = answer(posted).trim().slice(0, 300);
  }
  sessionProblem = 'SESSION: HTTP ' + status + (reason ? ': ' + reason : ' the article session refused the turn');
}
// A turn that answered 200 but wrote no article.md is a failed fetch, and the read below
// would see the error page as the draft: name the fetch rather than the missing H1.
let draftProblem = '';
if (fetched && Number(fetched.statusCode || fetched.status || 0) >= 400) {
  const status = Number(fetched.statusCode || fetched.status || 0);
  const reason = fetchedText.trim().slice(0, 300);
  draftProblem = 'DRAFT: HTTP ' + status + (reason ? ': ' + reason : ' the article session wrote no article.md');
}
const block = /<article>([\s\S]*?)<\/article>/.exec(raw);
const inner = (block ? block[1] : raw).trim();
const HEAD = /^#\s+(.+?)\s*$/;
let title = '';
const body = [];
for (const line of inner.split('\n')) {
  if (!title && !body.length && HEAD.test(line.trim())) {
    title = line.trim().replace(HEAD, '$1');
    continue;
  }
  body.push(line);
}
const text = body.join('\n').trim();
// A marker is an instruction to the publishing step, not prose the reader counts.
// A model cannot count words, so a draft a little over the budget is the budget met: 10%
// covers a counting slip without letting the article run long (row 3, 2026-10-30, died at
// 1248 words against 1200 with every other check passing). Integer arithmetic, because
// 1200 * 1.1 is 1320.0000000000002 in a double and Math.ceil would add a word.
const limit = Math.ceil(max * 11 / 10);
const words = text.replace(/<!--[\s\S]*?-->/g, ' ').split(/\s+/).filter(Boolean).length;
// The marker set is counted here rather than trusted to the review: how many markers a draft
// carries is a count, and a count a model is asked for is a count it misses. Both drafts of
// execution 14228 carried the same marker twice, the gate passed them, and the article ended up
// referencing one illustration twice.
const requested = String($('main_trigger').first().json.ASSET_TYPES || '')
  .split(',').map((s) => s.trim()).filter(Boolean);
const markers = (text.match(/<!--\s*asset:[a-zA-Z0-9_]+\s*-->/g) || [])
  .map((m) => m.replace('<!--', '').replace('-->', '').replace('asset:', '').trim());
const wrongMarkers = [
  ...requested.filter((t) => markers.filter((m) => m === t).length !== 1)
    .map((t) => t + ' x' + markers.filter((m) => m === t).length),
  ...markers.filter((m) => !requested.includes(m)).map((m) => m + ' not requested'),
];
// Every fence is a quotation. The ledger is the server's answer, not the model's: an entry
// whose URL did not answer was dropped before this node ran, and an entry the server could not
// find on the page is `found: false`. Whitespace is collapsed on both sides because the docs
// render the same YAML with other indentation; the excerpt is the page text the server matched,
// so comparing it to the block is the hash comparison without a crypto module Code nodes lack.
const norm = (value) => String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
const fenced = [];
{
  const re = /^[ \t]*```([^\n`]*)\n([\s\S]*?)^[ \t]*```[ \t]*$/gm;
  let m;
  while ((m = re.exec(text)) !== null) {
    const innerBlock = m[2].replace(/\n$/, '');
    if (innerBlock.trim()) fenced.push(innerBlock);
  }
}
const sourcesJSON = (() => {
  const res = read('fetch_sources');
  const body = answer(res);
  if (!body.trim()) return '';
  if (Number(res.statusCode || res.status || 0) >= 400) return '';
  return body;
})();
let ledger = [];
let ledgerRead = false;
let ledgerError = '';
if (sourcesJSON) {
  try {
    const data = JSON.parse(sourcesJSON);
    const list = Array.isArray(data) ? data : data && Array.isArray(data.sources) ? data.sources : null;
    if (!list) throw new Error('sources.json carries no sources array');
    ledger = list.filter((e) => e && norm(e.block) !== '');
    ledgerRead = true;
  } catch (e) {
    ledgerError = e.message;
  }
}
const firstLine = (value) => String(value || '').split('\n').map((l) => l.trim()).filter(Boolean)[0] || 'a fenced block';
const unverified = [];
let quoted = 0;
for (const fencedBlock of fenced) {
  const key = norm(fencedBlock);
  const head = firstLine(fencedBlock);
  const entry = ledger.find((e) => norm(e.block) === key);
  if (!entry) {
    unverified.push('UNQUOTED: "' + head + '" is not in sources.json');
    continue;
  }
  const url = String(entry.url || '').trim() || 'its url';
  if (entry.found !== true) {
    unverified.push('SOURCE_NOT_FOUND: "' + head + '" was not found at ' + url);
    continue;
  }
  const failure = String(entry.validation_error || '').trim();
  if (failure) {
    unverified.push('VALIDATION_FAILED: "' + head + '" (' + url + '): ' + failure);
    continue;
  }
  if (norm(entry.excerpt) !== key) {
    unverified.push('UNQUOTED: "' + head + '" no longer matches ' + url);
    continue;
  }
  quoted += 1;
}
let sourceProblem = '';
if (fenced.length && !ledgerRead) {
  sourceProblem = 'SOURCES: sources.json could not be read'
    + (ledgerError ? ' (' + ledgerError + ')' : '')
    + '; a fenced block cannot be verified';
} else if (unverified.length) {
  sourceProblem = unverified.join('; ');
}
let problem = '';
if (sessionProblem) problem = sessionProblem;
else if (draftProblem) problem = draftProblem;
else if (!text) problem = 'EMPTY_DRAFT: the model returned no article body';
else if (!title) problem = 'EMPTY_TITLE: the draft has no H1 title';
else if (words > limit) problem = 'OVER_BUDGET: ' + words + ' words against a limit of ' + limit + ' (MAX_WORDS=' + max + ')';
else if (wrongMarkers.length) problem = 'MARKERS: ' + wrongMarkers.join(', ');
else if (sourceProblem) problem = sourceProblem;
const describe = ledger
  .map((e) => '- ' + firstLine(e.block) + ' (' + (String(e.url || '').trim() || 'no url') + ')')
  .join('\n') || 'none';
return { json: {
  TITLE: title,
  TEXT: text,
  WORD_COUNT: words,
  MAX_WORDS: max,
  WORD_LIMIT: limit,
  SOURCES: ledgerRead ? sourcesJSON : '',
  SOURCES_TEXT: describe,
  SOURCES_NOTE: 'SOURCES: ' + quoted + ' quoted',
  FIDELITY: ledgerRead ? 'checked' : 'not run',
  PROBLEM: problem,
} };

// The verdict the loop branches on. The reviewer's answer is combined with the parser's
// deterministic checks, and the deterministic half wins: a count asked of a model is a
// count that gets invented, so `PROBLEM` rejects the draft whatever the reviewer said —
// and the reason then names the real numbers rather than the reviewer's guess.
const parsed = $('parse_article').item.json;
const reviewerSays = String($json.output || '').trim() === 'true';
const reason = String($json.explanation || '').replace(/\s+/g, ' ').trim();
const problem = String(parsed.PROBLEM || '');

const accepted = !problem && reviewerSays;
let explanation = '';
if (problem) explanation = problem + (reason ? ' ' + reason : '');
else if (!reviewerSays) explanation = reason || 'the reviewer rejected the draft without a reason';

return [{ json: { ...$json, output: accepted ? 'true' : 'false', explanation } }];

// The reviewer answers one verdict per draft as `<output>true|false</output>` and a short
// `<explanation>`. The explanation is flattened to one line because it has two readers: the
// next attempt's Reviewer Feedback block and the `MAX_RETRIES_EXCEEDED` report.
for (const item of $input.all()) {
  const { text } = item.json;

  const output = text.includes('<output>') && text.includes('</output>')
    ? text.split('<output>')[1].split('</output>')[0].trim().toLowerCase()
    : 'false';

  const explanation = text.includes('<explanation>') && text.includes('</explanation>')
    ? text.split('<explanation>')[1].split('</explanation>')[0].replace(/\s+/g, ' ').trim()
    : '';

  item.json.output = output;
  item.json.explanation = explanation;
}

return $input.all();

// The request the article session receives: the entry's fields, nothing that reads like
// an instruction. The prompt, the shapes and the audience levels live in the writer
// adapter, so this graph cannot drift from the text the model is given. `session_id` is the
// row, so a retry continues the session directory and its fetched corpus instead of paying
// for every source again, and `attempt` tells the adapter this turn is a correction. The
// source hosts ride on the request because the pod cannot read the deployment values:
// `AgentRuntime.spec` carries no env, so the allowlist the proxy enforces arrives here.
const vars = $('main_trigger').first().json;
const config = $('set_workflow_vars').first().json;
const row = String(vars.ROW_NUMBER || '').trim();
if (!row) throw new Error('ROW_NUMBER is required: the session id is article-<row>');
const base = String($env.ARTICLE_WRITER_URL || '').replace(/\/+$/, '');
if (!base) throw new Error('ARTICLE_WRITER_URL is not set; the article session cannot be reached');
const sessionId = ('article-' + row).replace(/[^A-Za-z0-9._-]/g, '').slice(0, 80);
const hosts = String(config.SOURCE_HOSTS || '').trim();
const explanation = String(($json && $json.explanation) || '').trim();
const feedback = [
  String(vars.FEEDBACK || '').trim(),
  explanation ? 'Internal review rejected the previous draft with: ' + explanation : '',
].filter(Boolean).join('\n');
const previous = $('parse_article').isExecuted ? String($('parse_article').last().json.TEXT || '') : '';
return [{ json: {
  SESSION_ID: sessionId,
  ATTEMPT: $runIndex + 1,
  ARTICLE_URL: base + '/v1/chat/completions',
  ARTIFACT_BASE: base + '/artifacts/' + sessionId,
  SOURCE_HOSTS: hosts,
  ARTICLE_BODY: JSON.stringify({
    session_id: sessionId,
    stream: false,
    source_hosts: hosts,
    attempt: $runIndex + 1,
    brief: {
      topic: String(vars.TOPIC || ''),
      description: String(vars.DESCRIPTION || ''),
      url: String(vars.URL || ''),
      max_words: Number(vars.MAX_WORDS) || 0,
      asset_types: String(vars.ASSET_TYPES || ''),
      audience: String(config.AUDIENCE || 'NONE'),
      extra_prompt: String(vars.EXTRA_PROMPT || ''),
      content: String(vars.CONTENT || ''),
      feedback,
      previous_draft: previous,
    },
  }),
} }];

